def load() -> pd.DataFrame:
    import glob
    files = glob.glob('data/environment/input/water-body-testing-*.csv')
    dfs = []
    for f in files:
        try:
            df = pd.read_csv(f)
            dfs.append(df)
        except Exception:
            pass
    return pd.concat(dfs, ignore_index=True)
